class CalError(Exception):
    def __init__(self, msg, code=1):
        self.msg=msg; self.code=code

@dataclass
class Recurrence:
    interval:int=1
    unit:str='D'
    until:date|None=None
    exceptions:set=field(default_factory=set)  # dates
    wdays:list=field(default_factory=list)     # encoded calcurse w values
    mdays:list=field(default_factory=list)
    months:list=field(default_factory=list)
    raw:str=''

@dataclass
class Item:
    kind:str
    desc:str
    start:datetime|None=None
    end:datetime|None=None
    event_days:int=1
    priority:int=0
    completed:bool=False
