#!/usr/bin/env python3
import sys, os, re, hashlib, calendar, shutil
from dataclasses import dataclass, field
from datetime import datetime, date, time, timedelta

VERSION = "4.8.2"
USAGE = """Usage:
calcurse [-D <directory>] [-C <directory>] [-c <calendar file>]
calcurse -Q [--from <date>] [--to <date>] [--days <number>]
calcurse -a | -d <date> | -d <number> | -n | -r[<number>] | -s[<date>] | -t[<number>]
calcurse -h | -v | --status | -G | -P | -g | -i <file> | -x[<format>] | --daemon"""
HELP = USAGE + """

Operations in command line mode:
  -Q, --query   Print items in a given query range
  -G, --grep    Grep items from the data files
  -P, --purge   Read items and write them back
Query short forms:
-a, -d <date>|<number>, -n, -r[<number>], -s[<date>], -t<number>

Note that filter, format and day-range options affect input or output:
  --filter-*              Filter items loaded by -Q, -G, -P and -x
  --format-*              Rewrite output from -Q, -G and --dump-imported
  --from <date>           Limit day range of -Q.
  --to <date>             Limit day range of -Q.
  --days <number>         Limit day range of -Q.

  --limit, -l <number>    Limit number of query results
  --search, -S <regexp>   Match regular expression in queries
Consult the man page for details.

Miscellaneous:
  -c, --calendar <file>   The calendar data file to use
  -C, --confdir <dir>     The configuration directory to use
  --daemon                Run notification daemon in the background
  -D, --datadir <dir>     The data directory to use
  -g, --gc                Run the garbage collector
  -h, --help              Show this help text
  -i, --import <file>     Import iCal data from file
  -q, --quiet             Suppress import/export result message
  --read-only             Do not save configuration or data files
  --status                Display status of running instances
  -v, --version           Show version information
  -x, --export[<format>]  Export to stdout in ical (default) or pcal format

For more information, type '?' from within calcurse, or read the manpage.
Submit feature requests and suggestions to <misc@calcurse.org>.
Submit bug reports to <bugs@calcurse.org>.
"""

class CalError(Exception):
    def __init__(self, msg, code=1):
        self.msg=msg; self.code=code

@dataclass
class Recurrence:
    interval:int=1
    unit:str='D'
    until:date|None=None
    exceptions:set=field(default_factory=set)  # dates
    wdays:list=field(default_factory=list)     # encoded calcurse w values
    mdays:list=field(default_factory=list)
    months:list=field(default_factory=list)
    raw:str=''

@dataclass
class Item:
    kind:str
    desc:str
    start:datetime|None=None
    end:datetime|None=None
    event_days:int=1
    priority:int=0
    completed:bool=False
    note:str=''
    recur:Recurrence|None=None
    raw:str=''

    def type_name(self):
        if self.kind == 'todo': return 'todo'
        if self.kind == 'event': return 'recur-event' if self.recur else 'event'
        return 'recur-apt' if self.recur else 'apt'

# ---------- Paths/config ----------
def default_dirs():
    home=os.environ.get('HOME','') or os.path.expanduser('~')
    old=os.path.join(home,'.calcurse')
    if os.path.isdir(old): return old, old
    xdg_data=os.environ.get('XDG_DATA_HOME', os.path.join(home,'.local','share'))
    xdg_conf=os.environ.get('XDG_CONFIG_HOME', os.path.join(home,'.config'))
    return os.path.join(xdg_data,'calcurse'), os.path.join(xdg_conf,'calcurse')

def ensure_data(datadir):
    os.makedirs(datadir, exist_ok=True)
    os.makedirs(os.path.join(datadir,'notes'), exist_ok=True)
    for f in ('apts','todo'):
        p=os.path.join(datadir,f)
        if not os.path.exists(p): open(p,'a').close()

# ---------- Date parsing/formatting ----------
def parse_input_date(s, fmt=1, allow_time=False):
    s=s.strip()
    tm=None
    if allow_time and ' ' in s:
        ds,ts=s.rsplit(' ',1)
        if re.match(r'^\d{1,2}:\d{2}$', ts):
            h,m=map(int,ts.split(':')); tm=time(h,m); s=ds
    low=s.lower()
    today=date.today()
    if low in ('today','now'):
        d=today
    elif low=='tomorrow': d=today+timedelta(days=1)
    elif low=='yesterday': d=today-timedelta(days=1)
    elif low[:3] in ['sun','mon','tue','wed','thu','fri','sat'] and len(low)>=3:
        target=['mon','tue','wed','thu','fri','sat','sun'].index(low[:3])
        delta=(target-today.weekday())%7
        d=today+timedelta(days=delta)
    else:
        nums=re.split(r'[-/]', s)
        if len(nums)!=3 or not all(re.match(r'^\d+$',x) for x in nums):
            raise CalError(f"args.c: 797: invalid date: {s}")
        a,b,c=map(int, nums)
        try:
            if fmt==1: d=date(c,a,b)
            elif fmt==2: d=date(c,b,a)
            elif fmt==3: d=date(a,b,c)
            elif fmt==4: d=date(a,b,c)
            else: d=date(c,a,b)
        except Exception:
            raise CalError(f"args.c: 797: invalid date: {s}")
    if tm: return datetime.combine(d, tm)
    return d

def fmt_date(d, outfmt='%m/%d/%y'):
    return d.strftime(outfmt)

def fmt_native_date(d): return d.strftime('%m/%d/%Y')
def fmt_native_dt(dt): return dt.strftime('%m/%d/%Y @ %H:%M')
def fmt_hm(dt): return dt.strftime('%H:%M')
def epoch(dt):
    return int(dt.timestamp())

def add_months(d, n):
    y=d.year + (d.month-1+n)//12
    m=(d.month-1+n)%12+1
    last=calendar.monthrange(y,m)[1]
    return date(y,m,min(d.day,last))

def valid_date(y,m,day):
    try: return date(y,m,day)
    except Exception: return None

def last_day(y,m): return calendar.monthrange(y,m)[1]

def sunday_wday(d): return (d.weekday()+1)%7

# ---------- Native parser ----------
def parse_recur(s):
    r=Recurrence(raw=s)
    toks=s.strip().split()
    if not toks: return r
    m=re.match(r'^(\d+)([DWMY])$', toks[0])
    if m: r.interval=int(m.group(1)); r.unit=m.group(2)
    i=1
    while i < len(toks):
        t=toks[i]
        if t=='->' and i+1<len(toks):
            try: r.until=parse_native_date(toks[i+1]); i+=2; continue
            except Exception: pass
        if t.startswith('!'):
            try: r.exceptions.add(parse_native_date(t[1:]))
            except Exception: pass
        elif t.startswith('w'):
            try: r.wdays.append(int(t[1:]))
            except Exception: pass
        elif t.startswith('d'):
            try: r.mdays.append(int(t[1:]))
            except Exception: pass
        elif t.startswith('m'):
            try: r.months.append(int(t[1:]))
            except Exception: pass
        i+=1
    return r

def native_recur(r):
    parts=[f"{r.interval}{r.unit}"]
    if r.until: parts += ['->', fmt_native_date(r.until)]
    for ex in sorted(r.exceptions): parts.append('!'+fmt_native_date(ex))
    for w in r.wdays: parts.append('w'+str(w))
    for d in r.mdays: parts.append('d'+str(d))
    for m in r.months: parts.append('m'+str(m))
    return ' '.join(parts)

def parse_native_date(s):
    m,d,y=map(int,s.split('/'))
    return date(y,m,d)

def parse_native_dt(s):
    mo=re.match(r'(\d\d)/(\d\d)/(\d{4}) @ (\d\d):(\d\d)', s)
    if not mo: raise ValueError(s)
    M,D,Y,h,m=map(int,mo.groups())
    return datetime(Y,M,D,h,m)

def parse_apts_line(line):
    raw=line.rstrip('\n')
    if not raw: return None
    # Appointment line: start -> end {recur} >note |desc
    if ' @ ' in raw and ' -> ' in raw:
        m=re.match(r'^(\d\d/\d\d/\d{4} @ \d\d:\d\d) -> (\d\d/\d\d/\d{4} @ \d\d:\d\d)(.*)$', raw)
        if not m: return None
        st=parse_native_dt(m.group(1)); en=parse_native_dt(m.group(2)); rest=m.group(3)
        rec=None; note=''
        rest=rest.lstrip()
        if rest.startswith('{'):
            j=rest.find('}')
            if j>=0:
                rec=parse_recur(rest[1:j]); rest=rest[j+1:].lstrip()
        if rest.startswith('>'):
            m2=re.match(r'^>([0-9a-fA-F]{40})\s*(.*)$', rest)
            if m2: note=m2.group(1); rest=m2.group(2)
        if rest.startswith('|'): desc=rest[1:]
        else: desc=rest.lstrip('| ')
        return Item('apt',desc,st,en,note=note,recur=rec,raw=raw)
    # Event line
    m=re.match(r'^(\d\d/\d\d/\d{4}) \[(\d+)\](.*)$', raw)
    if m:
        d=parse_native_date(m.group(1)); days=int(m.group(2)); rest=m.group(3).lstrip()
        rec=None; note=''
        if rest.startswith('{'):
            j=rest.find('}')
            if j>=0: rec=parse_recur(rest[1:j]); rest=rest[j+1:].lstrip()
        if rest.startswith('>'):
            m2=re.match(r'^>([0-9a-fA-F]{40})\s*(.*)$', rest)
            if m2: note=m2.group(1); rest=m2.group(2).lstrip()
        st=datetime.combine(d,time.min); en=st+timedelta(days=days)
        return Item('event',rest,st,en,event_days=days,note=note,recur=rec,raw=raw)
    return None

def parse_todo_line(line):
    raw=line.rstrip('\n')
    if not raw: return None
    m=re.match(r'^\[(-?\d+)\](.*)$', raw)
    if not m: return None
    pr=int(m.group(1)); completed=pr<0
    if completed: pr=abs(pr)
    rest=m.group(2).lstrip(); note=''
    if rest.startswith('>'):
        m2=re.match(r'^>([0-9a-fA-F]{40})\s*(.*)$', rest)
        if m2: note=m2.group(1); rest=m2.group(2)
    return Item('todo',rest,priority=pr,completed=completed,note=note,raw=raw)

def load_items(datadir, calendar_file=None):
    apts=[]; todos=[]
    aptfile=calendar_file or os.path.join(datadir,'apts')
    todofile=os.path.join(datadir,'todo')
    if os.path.exists(todofile):
        with open(todofile,errors='replace') as f:
            for line in f:
                it=parse_todo_line(line)
                if it: todos.append(it)
    if os.path.exists(aptfile):
        with open(aptfile,errors='replace') as f:
            for line in f:
                it=parse_apts_line(line)
                if it: apts.append(it)
    todos.sort(key=lambda x:(x.completed, x.priority, x.desc))
    apts.sort(key=lambda x:(x.start, 0 if x.kind=='event' else 1, x.desc))
    return todos+apts

# ---------- Raw serialization ----------
def item_raw(it):
    if it.raw: return it.raw
    if it.kind=='todo':
        pr = -it.priority if it.completed else it.priority
        s=f"[{pr}]"
        if it.note: s += '>'+it.note
        return s+' '+it.desc
    if it.kind=='event':
        s=f"{fmt_native_date(it.start.date())} [{it.event_days}]"
        if it.recur: s += ' {'+native_recur(it.recur)+'}'
        if it.note: s += ' >'+it.note
        return s+' '+it.desc
    s=f"{fmt_native_dt(it.start)} -> {fmt_native_dt(it.end)}"
    if it.recur: s += ' {'+native_recur(it.recur)+'}'
    if it.note: s += '>'+it.note+' '
    return s+'|'+it.desc

def save_items(datadir, items, calendar_file=None):
    ensure_data(datadir)
    aptfile=calendar_file or os.path.join(datadir,'apts')
    todofile=os.path.join(datadir,'todo')
    a=[it for it in items if it.kind!='todo']
    t=[it for it in items if it.kind=='todo']
    a.sort(key=lambda x:(x.start, 0 if x.kind=='event' else 1, x.desc))
    t.sort(key=lambda x:(x.completed, x.priority, x.desc))
    with open(aptfile,'w') as f:
        for it in a: f.write(item_raw(it)+'\n')
    with open(todofile,'w') as f:
        for it in t: f.write(item_raw(it)+'\n')

# ---------- Notes ----------
def note_text(datadir, note):
    if not note: return ''
    p=os.path.join(datadir,'notes',note)
    try: return open(p,errors='replace').read()
    except Exception: return ''

def fmt_note_for_output(txt):
    if txt=='': return ''
    # calcurse prefixes a tab to every line and leaves an extra newline after notes.
    lines=txt.splitlines()
    if txt.endswith('\n'):
        # splitlines drops final empty; output still has a tab-only line for empty note
        pass
    if not lines and txt.endswith('\n'):
        lines=['']
    out=''.join('\t'+l+'\n' for l in lines)
    return out+'\n'

def write_note(datadir, content):
    os.makedirs(os.path.join(datadir,'notes'), exist_ok=True)
    h=hashlib.sha1(content.encode()).hexdigest()
    with open(os.path.join(datadir,'notes',h),'w') as f: f.write(content)
    return h

# ---------- Recurrence occurrence generation ----------
def nth_weekday_of_month(y,m,weekday,ordv):
    # weekday Sunday=0
    days=[date(y,m,d) for d in range(1,last_day(y,m)+1) if sunday_wday(date(y,m,d))==weekday]
    if ordv>0:
        return days[ordv-1] if len(days)>=ordv else None
    else:
        return days[ordv] if len(days)>=abs(ordv) else None

def dates_for_month(y,m,r,base_day,base_wday):
    ds=[]
    mdays = r.mdays[:] if r.mdays else ([] if r.wdays else [base_day])
    for dd in mdays:
        dday = dd if dd>0 else last_day(y,m)+1+dd
        d=valid_date(y,m,dday)
        if d: ds.append(d)
    for w in r.wdays:
        if abs(w) > 6:
            ordv = int(w/7)  # trunc toward zero
            wd = abs(w) % 7 if w<0 else w % 7
            # for negative encoding -15 => ord=-2, weekday=1
            if w<0:
                ordv = - (abs(w)//7)
                wd = abs(w) % 7
            d=nth_weekday_of_month(y,m,wd,ordv)
            if d: ds.append(d)
        elif not r.mdays: # simple weekday: all matching days in month
            wd=w
            for day in range(1,last_day(y,m)+1):
                d=date(y,m,day)
                if sunday_wday(d)==wd: ds.append(d)
    if r.mdays and r.wdays:
        # intersection for simple weekday constraints such as Friday the 13th
        allowed={w for w in r.wdays if abs(w)<=6}
        if allowed: ds=[d for d in ds if sunday_wday(d) in allowed]
    return sorted(set(ds))

def recur_dates(it, start_day, end_day, limit=10000):
    r=it.recur
    base=it.start.date()
    if not r:
        return [base]
    res=[]
    max_until=r.until or end_day
    search_start=min(start_day, base)
    def add_if(d):
        if d < base: return
        if r.until and d > r.until: return
        if d in r.exceptions: return
        if start_day <= d <= end_day: res.append(d)
    if r.unit=='D':
        cur=base
        if start_day>base:
            n=max(0,(start_day-base).days//r.interval-2)
            cur=base+timedelta(days=n*r.interval)
        c=0
        while cur<=end_day and (not r.until or cur<=r.until) and c<limit:
            if not r.months or cur.month in r.months:
                add_if(cur)
            cur += timedelta(days=r.interval); c+=1
    elif r.unit=='W':
        # weeks anchored on Sunday of base week
        anchor=base-timedelta(days=sunday_wday(base))
        wdays=r.wdays[:] or [sunday_wday(base)]
        cur_anchor=anchor
        if start_day>anchor:
            weeks=((start_day-anchor).days//7)//r.interval*r.interval
            cur_anchor=anchor+timedelta(weeks=weeks)
        c=0
        while cur_anchor<=end_day+timedelta(days=7) and c<limit:
            for wd in wdays:
                d=cur_anchor+timedelta(days=wd)
                add_if(d)
            cur_anchor += timedelta(weeks=r.interval); c+=1
    elif r.unit=='M':
        months=(start_day.year-base.year)*12+(start_day.month-base.month)-r.interval-1
        n=max(0, months//r.interval*r.interval)
        c=0
        while c<limit:
            first=add_months(date(base.year,base.month,1), n)
            if first > end_day.replace(day=1)+timedelta(days=40): break
            for d in dates_for_month(first.year, first.month, r, base.day, sunday_wday(base)):
                add_if(d)
            n += r.interval; c+=1
            if r.until and first > r.until.replace(day=1)+timedelta(days=40): break
    elif r.unit=='Y':
        y=base.year + max(0, ((start_day.year-base.year)//r.interval-1)*r.interval)
        c=0
        while y <= end_day.year+1 and c<limit:
            months=r.months[:] or [base.month]
            for m in months:
                if r.wdays and any(abs(w)>6 for w in r.wdays) and not r.mdays:
                    # nth weekday of year for encodings like 20MO
                    for w in r.wdays:
                        if abs(w)>6:
                            ordv = (abs(w)//7) * (1 if w>0 else -1); wd=abs(w)%7
                            all_days=[]
                            for mm in (r.months or list(range(1,13))):
                                for dd in range(1,last_day(y,mm)+1):
                                    d=date(y,mm,dd)
                                    if sunday_wday(d)==wd: all_days.append(d)
                            if ordv>0 and len(all_days)>=ordv: add_if(all_days[ordv-1])
                            elif ordv<0 and len(all_days)>=abs(ordv): add_if(all_days[ordv])
                    continue
                for d in dates_for_month(y,m,r,base.day,sunday_wday(base)):
                    add_if(d)
            y += r.interval; c+=1
            if r.until and date(y,1,1)>r.until+timedelta(days=370): break
    return sorted(set(res))

def occurrences_on(it, day):
    if it.kind=='todo': return []
    occ=[]
    # Need dates whose interval overlaps day. For multi-day appointments/events, include continuation.
    dur=it.end-it.start
    start_search=day - timedelta(days=max(0,dur.days+2))
    for od in recur_dates(it,start_search,day):
        st=datetime.combine(od,it.start.time())
        en=st+dur
        if it.kind=='event':
            st=datetime.combine(od,time.min); en=st+timedelta(days=it.event_days)
        day_start=datetime.combine(day,time.min); day_end=day_start+timedelta(days=1)
        if st < day_end and en > day_start:
            occ.append((st,en))
    return occ

# ---------- Filtering ----------
def filter_match(it, opts):
    types=opts.get('filter_type')
    if types:
        exp=set()
        for p in types.split(','):
            if p=='cal': exp.update(['event','apt','recur-event','recur-apt'])
            elif p=='recur': exp.update(['recur-event','recur-apt'])
            else: exp.add(p)
        if it.type_name() not in exp: return False
    pat=opts.get('filter_pattern')
    if pat:
        try:
            if not re.search(pat,it.desc): return False
        except re.error:
            if pat not in it.desc: return False
    hp=opts.get('filter_hash')
    if hp:
        neg=hp.startswith('!'); pref=hp[1:] if neg else hp
        ok=item_hash(it).startswith(pref)
        if neg: ok=not ok
        if not ok: return False
    if it.kind=='todo':
        if opts.get('filter_priority') is not None and it.priority != int(opts['filter_priority']): return False
        if opts.get('filter_completed') and not it.completed: return False
        if opts.get('filter_uncompleted') and it.completed: return False
    else:
        for key, attr, incl in [
            ('filter_start_from','start',lambda x,y:x>=y),('filter_start_to','start',lambda x,y:x<=y),
            ('filter_start_after','start',lambda x,y:x>y),('filter_start_before','start',lambda x,y:x<y),
            ('filter_end_from','end',lambda x,y:x>=y),('filter_end_to','end',lambda x,y:x<=y),
            ('filter_end_after','end',lambda x,y:x>y),('filter_end_before','end',lambda x,y:x<y)]:
            if opts.get(key):
                dt=parse_input_date(opts[key], opts.get('input_fmt',1), allow_time=True)
                if isinstance(dt,date) and not isinstance(dt,datetime): dt=datetime.combine(dt,time.min)
                if not incl(getattr(it,attr), dt): return False
        for key, attr in [('filter_start_range','start'),('filter_end_range','end')]:
            if opts.get(key):
                a,b=opts[key].split(',',1)
                da=parse_input_date(a,opts.get('input_fmt',1),True); db=parse_input_date(b,opts.get('input_fmt',1),True)
                if isinstance(da,date) and not isinstance(da,datetime): da=datetime.combine(da,time.min)
                if isinstance(db,date) and not isinstance(db,datetime): db=datetime.combine(db,time.max)
                if not (da <= getattr(it,attr) <= db): return False
    return not opts.get('filter_invert') or False

def apply_filters(items, opts):
    out=[]
    inv=opts.get('filter_invert')
    for it in items:
        m=filter_match(it,{k:v for k,v in opts.items() if k!='filter_invert'})
        if inv: m=not m
        if m: out.append(it)
    return out

# ---------- Formatting ----------
def item_hash(it): return hashlib.sha1(item_raw(it).encode()).hexdigest()

def format_duration(sec, spec):
    if not spec: return str(sec)
    out=''; i=0
    while i<len(spec):
        if spec[i]=='%' and i+1<len(spec):
            j=i+1; nozero=False; extended=False
            if spec[j]=='-': nozero=True; j+=1
            if j<len(spec) and spec[j]=='E': extended=True; j+=1
            if j<len(spec):
                c=spec[j]
                val=None
                if c=='d': val=sec//86400
                elif c=='H': val=sec//3600 if extended else (sec//3600)%24
                elif c=='M': val=sec//60 if extended else (sec//60)%60
                elif c=='S': val=sec if extended else sec%60
                if val is not None:
                    out += str(val) if nozero else f"{val:02d}"; i=j+1; continue
        out += spec[i]; i+=1
    return out

def format_time_ext(dt, spec):
    if spec in ('', 'epoch'): return str(epoch(dt))
    if spec=='default': return dt.strftime('%H:%M')
    return dt.strftime(spec)

def apply_format(fmt, it, datadir, occ=None):
    st,en=(occ if occ else (it.start,it.end)) if it.kind!='todo' else (None,None)
    def repl_extended(name,arg):
        if name=='raw': return item_raw(it)
        if name=='hash': return item_hash(it)
        if name=='duration': return format_duration(int((en-st).total_seconds()) if st else 0, arg or '')
        if name=='remaining': return format_duration(int((st-datetime.now()).total_seconds()) if st else 0, arg or '')
        if name=='start': return format_time_ext(st, arg or 'epoch')
        if name=='end': return format_time_ext(en, arg or 'epoch')
        return '%('+name+((':'+arg) if arg else '')+')'
    out=''; i=0
    while i < len(fmt):
        if fmt[i]=='%' and i+1<len(fmt):
            if fmt[i+1]=='(':
                j=fmt.find(')',i+2)
                if j!=-1:
                    inner=fmt[i+2:j]
                    if ':' in inner: name,arg=inner.split(':',1)
                    else: name,arg=inner,''
                    out+=repl_extended(name,arg); i=j+1; continue
            c=fmt[i+1]; val=None
            if c=='m': val=it.desc
            elif c=='n': val=it.note
            elif c=='N': val=fmt_note_for_output(note_text(datadir,it.note))
            elif c=='p': val=str(it.priority)
            elif c=='s' and st: val=str(epoch(st))
            elif c=='e' and en: val=str(epoch(en))
            elif c=='d' and st: val=str(int((en-st).total_seconds()))
            elif c=='r' and st: val=str(int((st-datetime.now()).total_seconds()))
            elif c=='S' and st: val=st.strftime('%H:%M')
            elif c=='E' and en: val=en.strftime('%H:%M')
            elif c=='%': val='%'
            if val is not None:
                out+=val; i+=2; continue
        if fmt[i]=='\\' and i+1<len(fmt):
            maps={'n':'\n','t':'\t','r':'\r'}
            if fmt[i+1] in maps: out+=maps[fmt[i+1]]; i+=2; continue
        out+=fmt[i]; i+=1
    return out

def default_format(it, query=True):
    if not query: return '%(raw)'
    if it.kind=='todo': return '%p. %m\n'
    if it.kind=='event': return ' * %m\n'
    return ' - %S -> %E\n\t%m\n'

# ---------- Query/grep/export ----------
def query(items, opts, datadir):
    out=[]; count=0; limit=opts.get('limit')
    if limit is not None: limit=int(limit)
    inc_todos=any(it.kind=='todo' for it in items)
    inc_cal=any(it.kind!='todo' for it in items)
    if inc_todos:
        todos=[it for it in items if it.kind=='todo']
        if todos:
            out.append('to do:\n')
            fmt=opts.get('format_todo') or default_format(Item('todo',''), True)
            for it in todos:
                if limit is not None and count>=limit: break
                out.append(apply_format(fmt,it,datadir)); count+=1
            out.append('\n')
    if inc_cal:
        start=opts.get('from_date') or date.today()
        days=opts.get('days')
        to=opts.get('to_date')
        if days is not None:
            if days==0: raise CalError('args.c: 809: invalid range: 0')
            if days>0: begin=start; end=start+timedelta(days=days-1)
            else: begin=start+timedelta(days=days+1); end=start
        elif to is not None:
            begin=start; end=to
        else:
            begin=start; end=start
        if end<begin: raise CalError('args.c: 887: end date cannot come before start date')
        d=begin
        while d<=end:
            day_entries=[]
            for it in [x for x in items if x.kind!='todo']:
                for occ in occurrences_on(it,d):
                    day_entries.append((occ[0],0 if it.kind=='event' else 1,it,occ))
            day_entries.sort(key=lambda x:(x[0],x[1],x[2].desc))
            if day_entries:
                out.append(fmt_date(d,opts.get('output_fmt','%m/%d/%y'))+':\n')
                for _,__,it,occ in day_entries:
                    if limit is not None and count>=limit: break
                    key = 'format_recur_event' if it.kind=='event' and it.recur else 'format_event' if it.kind=='event' else 'format_recur_apt' if it.recur else 'format_apt'
                    fmt=opts.get(key) or default_format(it, True)
                    # continuation markers for default-ish %S/%E
                    s,e=occ
                    day_start=datetime.combine(d,time.min); day_end=day_start+timedelta(days=1)
                    disp_occ=(max(s,day_start), min(e,day_end))
                    text=apply_format(fmt,it,datadir,disp_occ)
                    if fmt==default_format(it,True):
                        if s.date()<d: text=text.replace(disp_occ[0].strftime('%H:%M'),'..:..',1)
                        if e.date()>d: text=text.replace(disp_occ[1].strftime('%H:%M'),'..:..',1)
                    out.append(text); count+=1
                out.append('\n')
            d+=timedelta(days=1)
    sys.stdout.write(''.join(out))

def grep_print(items, opts, datadir):
    for it in items:
        key = 'format_todo' if it.kind=='todo' else 'format_recur_event' if it.kind=='event' and it.recur else 'format_event' if it.kind=='event' else 'format_recur_apt' if it.recur else 'format_apt'
        fmt=opts.get(key) or '%(raw)'
        sys.stdout.write(apply_format(fmt,it,datadir))
        if not fmt.endswith('\n') and '\n' not in fmt[-2:]:
            # raw/default prints one line per item
            sys.stdout.write('\n')

def export_ical(items, opts, datadir):
    def esc(s): return s.replace('\\','\\\\').replace('\n','\\n').replace(',','\\,').replace(';','\\;')
    print('BEGIN:VCALENDAR')
    print('VERSION:2.0')
    print(f'PRODID:-//calcurse//NONSGML v{VERSION}//EN')
    for it in [x for x in items if x.kind!='todo']:
        print('BEGIN:VEVENT')
        if opts.get('export_uid'): print('UID:'+item_hash(it))
        if it.kind=='event':
            print('DTSTART;VALUE=DATE:'+it.start.strftime('%Y%m%d'))
            print('DURATION:P%dD'%it.event_days)
        else:
            print('DTSTART:'+it.start.strftime('%Y%m%dT%H%M%S'))
            sec=int((it.end-it.start).total_seconds())
            days,rem=divmod(sec,86400); h,rem=divmod(rem,3600); m,s=divmod(rem,60)
            if days: print(f'DURATION:P{days}DT{h}H{m}M{s}S')
            else: print(f'DURATION:PT{h}H{m}M{s}S')
        if it.recur:
            freq={'D':'DAILY','W':'WEEKLY','M':'MONTHLY','Y':'YEARLY'}[it.recur.unit]
            parts=[f'FREQ={freq}']
            if it.recur.interval!=1: parts.append(f'INTERVAL={it.recur.interval}')
            if it.recur.until: parts.append('UNTIL='+it.recur.until.strftime('%Y%m%d'))
            print('RRULE:'+';'.join(parts))
            if it.recur.exceptions:
                print('EXDATE:'+','.join(d.strftime('%Y%m%dT%H%M%S') for d in sorted(it.recur.exceptions)))
        print('SUMMARY:'+esc(it.desc))
        print('END:VEVENT')
    for it in [x for x in items if x.kind=='todo']:
        print('BEGIN:VTODO')
        if opts.get('export_uid'): print('UID:'+item_hash(it))
        if it.priority: print('PRIORITY:'+str(it.priority))
        if it.completed: print('STATUS:COMPLETED')
        print('SUMMARY:'+esc(it.desc))
        print('END:VTODO')
    print('END:VCALENDAR')

def export_pcal(items, opts, datadir):
    print('# calcurse pcal export\n')
    print('# =======\n# options\n# =======')
    print('opt -A -K -l -m -F Monday')
    print('# Display week number (i.e. 1-52) on every Monday')
