# ---------- iCalendar import ----------
def split_ical_prop(line):
    inq=False
    for i,ch in enumerate(line):
        if ch=='"': inq=not inq
        elif ch==':' and not inq:
            left=line[:i]; val=line[i+1:]
            parts=[]; cur=''; inq2=False
            for c in left:
                if c=='"': inq2=not inq2; cur+=c
                elif c==';' and not inq2: parts.append(cur); cur=''
                else: cur+=c
            parts.append(cur)
            name=parts[0].upper(); params={}
            for p in parts[1:]:
                if '=' in p:
                    k,v=p.split('=',1); params[k.upper()]=v.strip('"')
                else: params[p.upper()]=''
            return name,params,val
    return None,None,None

def ical_unescape(s):
    out=''; i=0
    while i<len(s):
        if s[i]=='\\' and i+1<len(s):
            c=s[i+1]
            if c in 'nN': out+='\n'
            elif c in ',;\\': out+=c
            else: out+=c
            i+=2
        else:
            out+=s[i]; i+=1
    return out

def valid_text_value(s):
    # unescaped commas/semicolons are invalid in these test assets, except common SUMMARY text may contain plain apostrophes/spaces.
    esc=False
    for ch in s:
        if esc: esc=False; continue
        if ch=='\\': esc=True; continue
        if ch==';': return False
    return True

def parse_ical_dt(val, params):
    isdate=params.get('VALUE','').upper()=='DATE'
    try:
        if isdate:
            if not re.match(r'^\d{8}$',val): return None, True
            return date(int(val[:4]),int(val[4:6]),int(val[6:8])), True
        else:
            v=val.rstrip('Z')
            if re.match(r'^\d{8}T\d{6}$',v):
                return datetime(int(v[:4]),int(v[4:6]),int(v[6:8]),int(v[9:11]),int(v[11:13]),int(v[13:15])), False
            if re.match(r'^\d{8}T\d{4}$',v):
                return datetime(int(v[:4]),int(v[4:6]),int(v[6:8]),int(v[9:11]),int(v[11:13])), False
            return None, False
    except Exception:
        return None, isdate

def parse_duration(s):
    m=re.match(r'^P(?:(\d+)W)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$', s)
    if not m: return None
    w,d,h,mi,se=[int(x or 0) for x in m.groups()]
    return timedelta(days=w*7+d,hours=h,minutes=mi,seconds=se)

def make_note_from_props(datadir, desc, loc, comment, import_msg=None):
    has_note = desc is not None or loc is not None or comment is not None or import_msg is not None
    if not has_note: return ''
    content=''
    if desc is not None:
        content += ical_unescape(desc) + '\n'
    extras=[]
    if loc is not None: extras.append('Location: '+ical_unescape(loc))
    if comment is not None:
        ct=ical_unescape(comment)
        lines=ct.split('\n')
        extras.append('Comment: '+lines[0] + ''.join('\n    '+l for l in lines[1:]))
    if import_msg: extras.append('Import: '+import_msg)
    if extras:
        content += '-- \n' + '\n'.join(extras) + '\n'
    return write_note(datadir, content)

def rrule_to_recur(rrule, start_dt, duration, is_event):
    parts={}
    for p in rrule.split(';'):
        if '=' in p:
            k,v=p.split('=',1); parts[k.upper()]=v
    freq=parts.get('FREQ','').upper()
    if freq not in ('DAILY','WEEKLY','MONTHLY','YEARLY'): return None
    r=Recurrence(interval=int(parts.get('INTERVAL','1') or '1'), unit={'DAILY':'D','WEEKLY':'W','MONTHLY':'M','YEARLY':'Y'}[freq])
    if 'BYMONTH' in parts:
        r.months=[int(x) for x in parts['BYMONTH'].split(',') if re.match(r'^-?\d+$',x)]
    if 'BYMONTHDAY' in parts:
        r.mdays=[int(x) for x in parts['BYMONTHDAY'].split(',') if re.match(r'^-?\d+$',x)]
    if 'BYDAY' in parts:
        mp={'SU':0,'MO':1,'TU':2,'WE':3,'TH':4,'FR':5,'SA':6}
        for tok in parts['BYDAY'].split(','):
            m=re.match(r'^([+-]?\d+)?(SU|MO|TU|WE|TH|FR|SA)$',tok)
            if m:
                ordv=int(m.group(1) or '0'); wd=mp[m.group(2)]
                r.wdays.append(wd if ordv==0 else ordv*7 + (wd if ordv>0 else -wd))
    if 'UNTIL' in parts:
        u=parts['UNTIL'].rstrip('Z')
        if is_event:
            if not re.match(r'^\d{8}$',u): return None
            r.until=date(int(u[:4]),int(u[4:6]),int(u[6:8]))
        else:
            if re.match(r'^\d{8}T\d{6}$',u):
                udt=datetime(int(u[:4]),int(u[4:6]),int(u[6:8]),int(u[9:11]),int(u[11:13]),int(u[13:15]))
                # last occurrence whose start+duration <= UNTIL; if DTSTART itself later, use until date
                cand=udt.date()
                if datetime.combine(cand,start_dt.time()) + duration > udt:
                    cand=cand-timedelta(days=1)
                r.until=cand
            elif re.match(r'^\d{8}$',u):
                r.until=date(int(u[:4]),int(u[4:6]),int(u[6:8]))
            else: return None
    if 'COUNT' in parts:
        count=int(parts['COUNT'])
        dummy=Item('event' if is_event else 'apt','', start_dt if isinstance(start_dt,datetime) else datetime.combine(start_dt,time.min), (start_dt if isinstance(start_dt,datetime) else datetime.combine(start_dt,time.min))+duration, recur=r)
        # generate a large range and choose count-th occurrence
        ds=recur_dates(dummy, dummy.start.date(), dummy.start.date()+timedelta(days=365*50), limit=20000)
        if len(ds)>=count: r.until=ds[count-1]
    return r

def import_ical(path, datadir, opts):
    ensure_data(datadir)
    raw_lines=open(path,errors='replace').read().splitlines()
    lines=[]
    for line in raw_lines:
        if line.startswith((' ', '\t')) and lines:
            lines[-1]+=line[1:]
        else: lines.append(line)
    items=[]; skipped=0; cur=None; props=[]
    def finish(kind, props):
        nonlocal skipped
        pd={}; pparams={}
        for name,params,val in props:
            pd.setdefault(name,[]).append(val); pparams.setdefault(name,[]).append(params)
        try:
            summary=pd.get('SUMMARY',[''])[0]
            if not valid_text_value(summary): raise ValueError()
            desc=summary and ical_unescape(summary) or ''
            if kind=='VTODO':
                pr=int(pd.get('PRIORITY',['0'])[0] or '0') if 'PRIORITY' in pd else 0
                if pr<0 or pr>9: raise ValueError()
                completed= any(v.upper()=='COMPLETED' for v in pd.get('STATUS',[]))
                # validate note fields
                for key in ('DESCRIPTION','COMMENT'):
                    if key in pd and not valid_text_value(pd[key][0]): raise ValueError()
                note=make_note_from_props(datadir, pd.get('DESCRIPTION',[None])[0], pd.get('LOCATION',[None])[0], pd.get('COMMENT',[None])[0])
                items.append(Item('todo',desc,priority=pr,completed=completed,note=note))
                return
            # VEVENT
            if 'DTSTART' not in pd: raise ValueError()
            st,isdate=parse_ical_dt(pd['DTSTART'][0], pparams['DTSTART'][0])
            if st is None: raise ValueError()
            if 'DTEND' in pd and 'DURATION' in pd: raise ValueError()
            dur=None; end=None
            if 'DURATION' in pd:
                dur=parse_duration(pd['DURATION'][0])
                if dur is None: raise ValueError()
                if isdate and dur.seconds!=0: raise ValueError()
            if 'DTEND' in pd:
                end,end_isdate=parse_ical_dt(pd['DTEND'][0], pparams['DTEND'][0])
                if end is None or end_isdate!=isdate: raise ValueError()
            if isdate:
                sdate=st
                if end is not None: days=(end-sdate).days
                elif dur is not None: days=dur.days
                else: days=1
                if days<=0: raise ValueError()
                import_msg=None; ev_days=days
                recur=None
                if 'RRULE' in pd:
                    recur=rrule_to_recur(pd['RRULE'][0], datetime.combine(sdate,time.min), timedelta(days=1), True)
                    if recur is None: raise ValueError()
                    ev_days=1
                    if days>1: import_msg='multi-day event changed to one-day event'
                elif days>1:
                    recur=Recurrence(1,'D',sdate+timedelta(days=days-1))
                    ev_days=1; import_msg='multi-day event changed to one-day event'
                for key in ('DESCRIPTION','COMMENT'):
                    if key in pd and not valid_text_value(pd[key][0]): raise ValueError()
                note=make_note_from_props(datadir, pd.get('DESCRIPTION',[None])[0], pd.get('LOCATION',[None])[0], pd.get('COMMENT',[None])[0], import_msg)
                if recur and 'EXDATE' in pd:
                    for vals,params in zip(pd['EXDATE'],pparams['EXDATE']):
                        for vv in vals.split(','):
                            ex,ex_isdate=parse_ical_dt(vv,params)
                            if ex is None or not ex_isdate: raise ValueError()
                            recur.exceptions.add(ex)
                elif 'EXDATE' in pd: raise ValueError()
                items.append(Item('event',desc,datetime.combine(sdate,time.min),datetime.combine(sdate,time.min)+timedelta(days=ev_days),event_days=ev_days,note=note,recur=recur))
            else:
                sdt=st
                if end is not None: edt=end
                elif dur is not None: edt=sdt+dur
                else: edt=sdt
                if edt<sdt: raise ValueError()
                duration=edt-sdt
                recur=None
                if 'RRULE' in pd:
                    recur=rrule_to_recur(pd['RRULE'][0], sdt, duration, False)
                    if recur is None: raise ValueError()
                if recur and 'EXDATE' in pd:
                    for vals,params in zip(pd['EXDATE'],pparams['EXDATE']):
                        for vv in vals.split(','):
                            ex,ex_isdate=parse_ical_dt(vv,params)
                            if ex is None or ex_isdate: raise ValueError()
                            recur.exceptions.add(ex.date())
                elif 'EXDATE' in pd: raise ValueError()
                for key in ('DESCRIPTION','COMMENT'):
                    if key in pd and not valid_text_value(pd[key][0]): raise ValueError()
                note=make_note_from_props(datadir, pd.get('DESCRIPTION',[None])[0], pd.get('LOCATION',[None])[0], pd.get('COMMENT',[None])[0])
                items.append(Item('apt',desc,sdt,edt,note=note,recur=recur))
        except Exception:
            skipped += 1
    for line in lines:
        name,params,val=split_ical_prop(line)
        if name=='BEGIN' and val in ('VEVENT','VTODO'):
            cur=val; props=[]
        elif name=='END' and val in ('VEVENT','VTODO') and cur==val:
            finish(cur,props); cur=None; props=[]
        elif cur:
            if name is None:
                # malformed property: ignore except for descriptions/summary? original skips item often
                if line.startswith(('SUMMARY','DESCRIPTION','EXDATE')): props.append(('__BAD__',{},''))
                continue
            props.append((name,params,val))
    if cur: skipped+=1
    # Existing + new, sort/save
    all_items=load_items(datadir)+items
    save_items(datadir,all_items)
    apps=sum(1 for i in items if i.kind=='apt'); events=sum(1 for i in items if i.kind=='event'); todos=sum(1 for i in items if i.kind=='todo')
    if opts.get('dump_imported'):
        grep_print(items, opts, datadir)
    if not opts.get('quiet'):
        print(f"Import process report: {len(raw_lines):04d} lines read")
        def plural(n,word): return word if n==1 else word+'s'
        print(f"{apps} {plural(apps,'app')} / {events} {plural(events,'event')} / {todos} {plural(todos,'todo')} / {skipped} skipped")
    if skipped:
        sys.stderr.write('\nSome items could not be imported.\nSee /tmp/calcurse_log.XXXXXX for details.\n')
        return 1
    return 0

# ---------- CLI ----------
def parse_args(argv):
    opts={'input_fmt':1, 'output_fmt':'%m/%d/%y'}; mode=None; i=0
    def need(arg):
        nonlocal i
        if i+1>=len(argv):
            sys.stderr.write(f"./executable: option requires an argument -- '{arg}'\n")
            print(USAGE); print("Try `calcurse -h` for more information.")
            raise SystemExit(1)
        i+=1; return argv[i]
    while i<len(argv):
        a=argv[i]
        if a in ('-h','--help'): mode='help'
        elif a in ('-v','--version'): mode='version'
        elif a=='--status': mode='status'
        elif a=='--daemon': mode='daemon'
        elif a in ('-q','--quiet'): opts['quiet']=True
        elif a=='--read-only': opts['read_only']=True
        elif a in ('-D','--datadir'): opts['datadir']=need('D')
        elif a in ('-C','--confdir','--directory'): opts['confdir']=need('C')
        elif a in ('-c','--calendar'): opts['calendar']=need('c')
        elif a in ('-i','--import'): mode='import'; opts['import_file']=need('i')
        elif a=='--dump-imported': opts['dump_imported']=True
        elif a=='--export-uid': opts['export_uid']=True
        elif a.startswith('-x') and a!='-x': mode='export'; opts['export_format']=a[2:]
        elif a.startswith('--export='): mode='export'; opts['export_format']=a.split('=',1)[1]
        elif a in ('-x','--export'): mode='export';
        elif a in ('-G','--grep'): mode='grep'
        elif a in ('-P','--purge','-F','--filter'): mode='purge'
        elif a in ('-g','--gc'): mode='gc'
        elif a in ('-Q','--query'): mode='query'
        elif a in ('-a','--appointment'): mode='query'; opts['filter_type']='cal'
        elif a.startswith('-d') and a!='-d': mode='day'; opts['day_arg']=a[2:]
        elif a in ('-d','--day'): mode='day'; opts['day_arg']=need('d')
        elif a.startswith('-r') and a!='-r': mode='range'; opts['range_arg']=a[2:] or '1'
        elif a in ('-r','--range'): mode='range'; opts['range_arg']='1'
        elif a.startswith('--range='): mode='range'; opts['range_arg']=a.split('=',1)[1] or '1'
        elif a.startswith('-s') and a!='-s': mode='startday'; opts['start_arg']=a[2:]
        elif a in ('-s','--startday'): mode='startday'; opts['start_arg']='today'
        elif a.startswith('--startday='): mode='startday'; opts['start_arg']=a.split('=',1)[1] or 'today'
        elif a.startswith('-t') and a!='-t': mode='todo'; opts['todo_arg']=a[2:]
        elif a in ('-t','--todo'): mode='todo'; opts['todo_arg']=None
        elif a.startswith('--todo='): mode='todo'; opts['todo_arg']=a.split('=',1)[1]
        elif a in ('-n','--next'): mode='next'
        elif a in ('-l','--limit'): opts['limit']=need('l')
        elif a.startswith('--limit='): opts['limit']=a.split('=',1)[1]
        elif a in ('-S','--search','--filter-pattern'): opts['filter_pattern']=need('S' if a=='-S' else '')
        elif a.startswith('--search='): opts['filter_pattern']=a.split('=',1)[1]
        elif a=='--filter-type': opts['filter_type']=need('')
        elif a.startswith('--filter-type='): opts['filter_type']=a.split('=',1)[1]
        elif a=='--filter-invert': opts['filter_invert']=True
        elif a=='--filter-hash': opts['filter_hash']=need('')
        elif a.startswith('--filter-hash='): opts['filter_hash']=a.split('=',1)[1]
        elif a in ('--filter-start-from','--filter-start-to','--filter-start-after','--filter-start-before','--filter-start-range','--filter-end-from','--filter-end-to','--filter-end-after','--filter-end-before','--filter-end-range','--filter-priority'):
            opts[a[2:].replace('-','_')]=need('')
        elif any(a.startswith(x+'=') for x in ('--filter-start-from','--filter-start-to','--filter-start-after','--filter-start-before','--filter-start-range','--filter-end-from','--filter-end-to','--filter-end-after','--filter-end-before','--filter-end-range','--filter-priority')):
            k,v=a[2:].split('=',1); opts[k.replace('-','_')]=v
        elif a=='--filter-completed': opts['filter_completed']=True
        elif a=='--filter-uncompleted': opts['filter_uncompleted']=True
        elif a=='--from': opts['from_raw']=need('')
        elif a.startswith('--from='): opts['from_raw']=a.split('=',1)[1]
        elif a=='--to': opts['to_raw']=need('')
        elif a.startswith('--to='): opts['to_raw']=a.split('=',1)[1]
        elif a=='--days': opts['days']=int(need(''))
        elif a.startswith('--days='): opts['days']=int(a.split('=',1)[1])
        elif a=='--input-datefmt': opts['input_fmt']=int(need(''))
        elif a.startswith('--input-datefmt='): opts['input_fmt']=int(a.split('=',1)[1])
        elif a=='--output-datefmt': opts['output_fmt']=need('')
        elif a.startswith('--output-datefmt='): opts['output_fmt']=a.split('=',1)[1]
        elif a in ('--format-apt','--format-recur-apt','--format-event','--format-recur-event','--format-todo'):
            opts[a[2:].replace('-','_')]=need('')
        elif any(a.startswith(x+'=') for x in ('--format-apt','--format-recur-apt','--format-event','--format-recur-event','--format-todo')):
            k,v=a[2:].split('=',1); opts[k.replace('-','_')]=v
        elif a.startswith('--'):
            sys.stderr.write(f"./executable: unrecognized option '{a}'\n"); print(USAGE); print("Try `calcurse -h` for more information."); raise SystemExit(1)
        elif a.startswith('-'):
            sys.stderr.write(f"./executable: invalid option -- '{a[1:2]}'\n"); print(USAGE); print("Try `calcurse -h` for more information."); raise SystemExit(1)
        i+=1
    return mode,opts

def normalize_query_short(mode, opts):
    if mode=='day':
        a=opts['day_arg']
        opts['filter_type']='cal'; mode='query'
        if re.match(r'^-?\d+$',a): opts['days']=int(a)
        else: opts['from_date']=parse_input_date(a, opts['input_fmt'])
    elif mode=='range':
        opts['filter_type']='cal'; opts['days']=int(opts.get('range_arg') or '1'); mode='query'
    elif mode=='startday':
        opts['filter_type']='cal'; opts['from_date']=parse_input_date(opts.get('start_arg') or 'today', opts['input_fmt']); mode='query'
    elif mode=='todo':
        opts['filter_type']='todo'; arg=opts.get('todo_arg')
        if arg is not None and arg!='':
            n=int(arg)
            if n<0 or n>9: raise CalError(f'args.c: 612: invalid priority: {n}')
            if n==0: opts['filter_completed']=True
            else: opts['filter_priority']=str(n); opts['filter_uncompleted']=True
        mode='query'
    if opts.get('from_raw'): opts['from_date']=parse_input_date(opts['from_raw'],opts['input_fmt'])
    if opts.get('to_raw'): opts['to_date']=parse_input_date(opts['to_raw'],opts['input_fmt'])
    return mode

def main(argv):
    mode,opts=parse_args(argv)
    datadir,confdir=default_dirs()
    if opts.get('datadir'): datadir=opts['datadir']
    if opts.get('confdir'): confdir=opts['confdir']
    calfile=opts.get('calendar')
    try:
        mode=normalize_query_short(mode, opts)
        if mode is None:
            # interactive: mimic ncurses failure in non-terminal environments
            sys.stderr.write('Error opening terminal: unknown.\n'); return 1
        if mode=='help': print(HELP,end=''); return 0
        if mode=='version':
            print(f'calcurse {VERSION} -- text-based organizer\n')
            print('Copyright (c) 2004-2023 calcurse Development Team.')
            print('This is free software; see the source for copying conditions.')
            return 0
        if mode=='status': print('calcurse is not running'); return 0
        if mode=='daemon': ensure_data(datadir); return 0
        if mode=='gc':
            items=load_items(datadir,calfile); refs={it.note for it in items if it.note}
            nd=os.path.join(datadir,'notes')
            if os.path.isdir(nd):
                for fn in os.listdir(nd):
                    if fn not in refs:
                        try: os.remove(os.path.join(nd,fn))
                        except Exception: pass
            return 0
        if mode=='import': return import_ical(opts['import_file'],datadir,opts)
        items=load_items(datadir,calfile)
        items=apply_filters(items,opts)
        if mode=='grep': grep_print(items,opts,datadir); return 0
        if mode=='purge':
            if not opts.get('read_only'):
                # Remove matching from all items; apply_filters returned matching, so keep complement.
                rem_hash={item_hash(x) for x in items}
                all_items=load_items(datadir,calfile)
                save_items(datadir,[x for x in all_items if item_hash(x) not in rem_hash],calfile)
            return 0
        if mode=='export':
            fmt=opts.get('export_format','ical') or 'ical'
            if fmt not in ('ical','pcal'): raise CalError(f'args.c: 631: invalid export format: {fmt}')
            if fmt=='ical': export_ical(items,opts,datadir)
            else: export_pcal(items,opts,datadir)
            return 0
        if mode=='next':
            now=datetime.now(); best=None; bestit=None
            for it in items:
                if it.kind=='apt':
                    for d in recur_dates(it,now.date(),(now+timedelta(days=1)).date()):
                        st=datetime.combine(d,it.start.time())
                        if now <= st <= now+timedelta(days=1) and (best is None or st<best): best=st; bestit=it
            if best:
                delta=best-now; mins=int(delta.total_seconds()//60); h,m=divmod(mins,60)
                print(f'next appointment:\n   [{h:02d}:{m:02d}] {bestit.desc}')
            return 0
        if mode=='query': query(items,opts,datadir); return 0
        return 0
    except CalError as e:
        sys.stderr.write(e.msg+'\n'); return e.code

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))
